"""Readable catalogue generated from the frozen population; never reruns agents."""
from pathlib import Path
import json, csv, html
root=Path(__file__).resolve().parent.parent
pub=json.loads((root/'data/published-experiment.json').read_text());rid=pub['run_id'];folder=root/'data/exploration'/rid
profiles=json.loads((folder/'population.json').read_text());assert len(profiles)==256
web=root/'web/product';esc=lambda x:html.escape(str(x),quote=True)
fields=['id','kind','role','topic','objective','strategy','interaction_preference','peer_trust','room','profile_hash']
with (web/'agent-profiles.csv').open('w',newline='') as f:
 writer=csv.DictWriter(f,fieldnames=fields);writer.writeheader();writer.writerows({k:p[k] for k in fields} for p in profiles)
cards=[]
for p in profiles:
 links=''.join(f'<a href="../#agents?arm={arm}&amp;agent={p["id"]}" target="_blank" rel="noopener">{label} ↗</a>' for arm,label in [('baseline','A / Unprotected trace'),('protected','B / ArmorIQ trace')])
 cards.append(f'''<article data-kind="{p['kind']}"><header><span class="mono">{p['id']}</span><span class="kind {p['kind']}">{esc(p['kind'])}</span></header><h2>{esc(p['role'].replace('-',' '))}<span> / {esc(p['topic'])}</span></h2><p class="objective">{esc(p['objective'])}</p><p class="strategy"><b>Approach</b> {esc(p['strategy'])}</p><details><summary>Full profile &amp; granted authority</summary><pre>{esc(json.dumps(p,indent=2))}</pre></details><footer>{links}</footer></article>''')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>All 256 agent profiles · Boundary</title><style>
@font-face{font-family:DM;src:url('fonts/dm-sans.woff2')}*{box-sizing:border-box}body{margin:0;background:#f7f8f3;color:#1d251f;font-family:DM,system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:40px 32px}nav,header,footer,.tools{display:flex;align-items:center;justify-content:space-between;gap:16px}nav{padding-bottom:24px;border-bottom:1px solid #cfd4c7}a{color:#365e46;text-underline-offset:4px}h1{font-size:clamp(40px,5vw,68px);line-height:1.08;letter-spacing:-.045em;margin:46px 0 20px}h1+p{font-size:19px;max-width:800px;line-height:1.6}.mono,.kind{font-family:ui-monospace,monospace;font-size:12px}.tools{position:sticky;top:0;z-index:2;padding:18px 0;background:#f7f8f3;flex-wrap:wrap}input,select{font:inherit;padding:12px;border:1px solid #bdc6b8;background:white;border-radius:3px}input{flex:1;min-width:200px}#catalogue{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}article{border:1px solid #ccd2c5;background:#fff;padding:25px;min-width:0}h2{font-size:23px;margin:24px 0 16px;font-weight:550}h2 span{color:#73806f;font-weight:400}.objective{line-height:1.65;margin:0 0 22px}.strategy{font-size:14px;line-height:1.6;color:#61705d}.strategy b{font-size:11px;text-transform:uppercase;letter-spacing:.1em;display:block}.kind{padding:5px 8px;border-radius:2px;background:#edeedc}.kind.legitimate{background:#e4eee4;color:#365e46}.kind.adversarial{background:#fae9e2;color:#a94a2f}details{border-top:1px solid #e2e5dc;padding:16px 0;font-size:13px}summary{cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.7}footer{border-top:1px solid #e2e5dc;padding-top:18px;flex-wrap:wrap;font-size:13px}[hidden]{display:none!important}.notes{line-height:1.7;font-size:14px;color:#61705d;margin:24px 0 40px}.downloads{display:flex;gap:20px;flex-wrap:wrap;margin:28px 0}small{color:#61705d}input:focus-visible,select:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid #477556;outline-offset:4px}@media(max-width:760px){main{padding:24px 18px}#catalogue{grid-template-columns:1fr}article{padding:20px}nav{align-items:flex-start}.tools{gap:10px}}
</style><main><nav><strong>boundary / population</strong><a href="../">Experiment overview ↗</a></nav><h1>256 agents.<br>What each was trying to do.</h1><p>Exact objectives and approaches from the frozen run profiles. Open either website’s trail for the same agent to compare its recorded choices, messages, requests and responses.</p><div class="notes">Run <code>RUN_ID</code> · 32 objective families × 8 topics.<br>96 legitimate · 96 adversarial · 64 under pressure. These categories describe assigned objectives; they do not prove every action succeeded or caused harm. Each site used fresh model memories.<br>Traces expose recorded decisions, inputs, messages and tool feedback. Private model reasoning is not available.</div><div class="downloads"><a href="agent-profiles.csv" download>All profiles / CSV ↓</a><a href="../proof/population.json" download>Original profiles / JSON ↓</a><a href="../proof/baseline.jsonl" download>All unprotected events / JSONL ↓</a><a href="../proof/protected.jsonl" download>All protected events / JSONL ↓</a></div><div class="tools"><input id="search" type="search" aria-label="Search all profiles" placeholder="Search ID, objective, strategy, role or topic"><select id="kind" aria-label="Profile category"><option value="all">All categories</option><option value="legitimate">Legitimate</option><option value="adversarial">Adversarial</option><option value="pressure">Under pressure</option></select><small id="count" aria-live="polite">256 of 256 profiles</small></div><section id="catalogue">CARDS</section><p id="empty" hidden>No profiles match your search.</p></main><script>const cards=[...document.querySelectorAll('article')],search=document.querySelector('#search'),kind=document.querySelector('#kind');function filter(){let count=0;for(const c of cards){c.hidden=!(c.textContent.toLowerCase().includes(search.value.toLowerCase().trim())&&(kind.value==='all'||c.dataset.kind===kind.value));if(!c.hidden)count++}document.querySelector('#count').textContent=count+' of 256 profiles';document.querySelector('#empty').hidden=count!==0}search.addEventListener('input',filter);kind.addEventListener('change',filter)</script></html>'''.replace('RUN_ID',rid).replace('CARDS',''.join(cards))
(web/'agent-profiles.html').write_text(page)
print('Created searchable catalogue and objective CSV from all',len(profiles),'frozen profiles')
